// primitives.js — tiny DOM helpers + reusable components (Icon, Sparkline, etc.)
// Pure vanilla ES module — no React, no JSX. Returns Strings (HTML) or Elements.

// Vendored icon data (generated by scripts/gen_web_icons.py): heroicons for the
// UI glyphs (stroke/currentColor) + simple-icons for brand marks (fill). The
// hand-rolled ICONS map below stays as the fallback for the handful of names
// heroicons has no match for (command=⌘, git=branch, coffee).
import { HEROICONS, BRANDS } from './icon_data.js';

// ── escape ─────────────────────────────────────────────────────────
export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[c]));

// ── shorthand DOM construction ────────────────────────────────────
export function h(tag, props = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(props || {})) {
    if (v == null || v === false) continue;
    if (k === 'class' || k === 'className') {
      el.className = String(v);
    } else if (k === 'style' && typeof v === 'object') {
      Object.assign(el.style, v);
    } else if (k === 'dataset' && typeof v === 'object') {
      for (const [dk, dv] of Object.entries(v)) el.dataset[dk] = String(dv);
    } else if (k.startsWith('on') && typeof v === 'function') {
      el.addEventListener(k.slice(2).toLowerCase(), v);
    } else if (k === 'html') {
      el.innerHTML = v;
    } else if (v === true) {
      el.setAttribute(k, '');
    } else {
      el.setAttribute(k, v);
    }
  }
  for (const c of children.flat()) {
    if (c == null || c === false) continue;
    if (c instanceof Node) el.appendChild(c);
    else el.appendChild(document.createTextNode(String(c)));
  }
  return el;
}

