// Brand mark (concentric threads suggesting a relaydeck)
export const BRAND_SVG = `
  <svg class="brand-mark" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round">
    <circle cx="9" cy="9" r="7.5"/>
    <path d="M2 9 H16"/>
    <path d="M9 1.5 V16.5"/>
    <path d="M3.5 3.5 L14.5 14.5"/>
    <path d="M14.5 3.5 L3.5 14.5"/>
  </svg>`;

export function iconSVG(name, size = 14) {
  // Prefer the vendored heroicon; fall back to the hand-rolled glyph.
  const body = HEROICONS[name] || ICONS[name];
  if (!body) return '';
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" style="display:inline-block;flex-shrink:0;vertical-align:middle">${body}</svg>`;
}

// Every icon name iconSVG() can resolve (heroicon override + hand-rolled
// fallback). Surfaces that validate plugin-supplied icon names use this so a
// freshly-vendored icon isn't sanitized away to a fallback glyph.
export function knownIconNames() {
  return new Set([...Object.keys(HEROICONS), ...Object.keys(ICONS)]);
}

// ── Brand marks (simple-icons) ────────────────────────────────────
// Fill-based single-path logos for harnesses + model providers. Tinted with
// `color` (default currentColor, so CSS `color:` controls it).
export function brandHex(slug) { return BRANDS[slug]?.hex || null; }
export function hasBrand(slug) { return !!BRANDS[slug]; }
export function brandSVG(slug, size = 16, color = 'currentColor') {
  const b = BRANDS[slug];
  if (!b) return '';
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="${color}" style="display:inline-block;flex-shrink:0;vertical-align:middle"><path d="${b.path}"/></svg>`;
}

// Model-provider name → simple-icons slug. Providers relaydeck resolves to
// (anthropic/openai/google/ollama/…) get an authentic logo; unknowns render
// nothing (callers fall back to text).
const PROVIDER_SLUG = {
  anthropic: 'anthropic', openai: 'openai', azure: 'openai',
  google: 'googlegemini', gemini: 'googlegemini', 'google-gemini': 'googlegemini', vertex: 'googlegemini',
  ollama: 'ollama', deepseek: 'deepseek', mistral: 'mistralai', mistralai: 'mistralai',
  openrouter: 'openrouter', meta: 'meta', llama: 'meta', 'meta-llama': 'meta',
  xai: 'x', grok: 'x', x: 'x', perplexity: 'perplexity',
  huggingface: 'huggingface', hf: 'huggingface',
};
export function providerSlug(name) {
  if (!name) return null;
  return PROVIDER_SLUG[String(name).toLowerCase().trim()] || null;
}
/** Authentic provider logo (tinted to its brand hex), or '' if unknown. */
export function providerMark(name, size = 14) {
  const slug = providerSlug(name);
  if (!slug) return '';
  return brandSVG(slug, size, brandHex(slug) || 'currentColor');
}

// ── Sparkline ─────────────────────────────────────────────────────
export function sparklineSVG(data, opts = {}) {
  const { width = 100, height = 28, color = 'var(--acc)', fill = true, dot = true, strokeWidth = 1.4 } = opts;
  if (!data || data.length === 0) return '';
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const step = width / (data.length - 1 || 1);
  const pts = data.map((v, i) => [i * step, height - ((v - min) / range) * (height - 2) - 1]);
  const linePath = pts.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const fillPath = `${linePath} L${width},${height} L0,${height} Z`;
  const last = pts[pts.length - 1];
  return `<svg class="spark" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" style="width:100%;height:${height}px">
    ${fill ? `<path d="${fillPath}" fill="${color}" opacity="0.12"/>` : ''}
    <path d="${linePath}" fill="none" stroke="${color}" stroke-width="${strokeWidth}"/>
    ${dot ? `<circle cx="${last[0]}" cy="${last[1]}" r="1.8" fill="${color}"/>` : ''}
  </svg>`;
}

// ── Area chart (filled SVG, for Models hero cards) ────────────────
export function areaChartSVG(data, opts = {}) {
  const { height = 120, color = 'var(--acc)' } = opts;
  if (!data || data.length === 0) return '';
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const w = 100;
  const stepX = w / (data.length - 1 || 1);
  const pts = data.map((v, i) => [i * stepX, height - ((v - min) / range) * (height - 10) - 5]);
  const line = pts.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
  const fill = `${line} L${w},${height} L0,${height} Z`;
  const id = `g-${Math.random().toString(36).slice(2, 8)}`;
  return `<svg class="area-chart" viewBox="0 0 ${w} ${height}" preserveAspectRatio="none">
    <defs>
      <linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${color}" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
      </linearGradient>
    </defs>
    <path d="${fill}" fill="url(#${id})"/>
    <path d="${line}" fill="none" stroke="${color}" stroke-width="1.5" vector-effect="non-scaling-stroke"/>
  </svg>`;
}

// ── Number formatting ─────────────────────────────────────────────
export function fmtNum(n) {
  n = Number(n) || 0;
  if (n >= 1e6) return (n / 1e6).toFixed(2) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(1) + 'k';
  return String(Math.round(n));
}

export function fmtCost(n) {
  n = Number(n) || 0;
  if (n === 0) return '$0.00';
  if (n < 0) return '-' + fmtCost(-n);
  if (n >= 0.01) return '$' + n.toFixed(2);
  // Sub-cent costs are real (a small run can cost a fraction of a cent) —
  // show 2 significant figures instead of collapsing to "< $0.01", which
  // read as "not calculated". Avoid scientific notation for tiny values.
  let s = n.toPrecision(2);
  if (s.includes('e')) s = n.toFixed(8).replace(/0+$/, '').replace(/\.$/, '');
  return '$' + s;
}

// Human-readable byte size (IEC, base-1024). Null/NaN → em dash so a
// missing stat reads as "unknown", not "0 B".
export function fmtBytes(n) {
  if (n == null || Number.isNaN(Number(n))) return '—';
  n = Number(n);
  if (n < 1024) return `${Math.round(n)} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let u = -1;
  do { n /= 1024; u++; } while (n >= 1024 && u < units.length - 1);
  return `${n < 10 ? n.toFixed(1) : Math.round(n)} ${units[u]}`;
}

// Normalize any timestamp this app sees to epoch MILLISECONDS.
//
// Backend timestamps are epoch SECONDS (Python time.time()), and some
// endpoints serialize them as a numeric *string* (e.g. messages.py
// `f"{ts:.0f}"`). JS Date/Date.now() are milliseconds. Historically each
// call site multiplied numeric backend values by 1000, and any site that
// forgot rendered "~20000d ago" (a seconds value read as ms).
//
// We normalize centrally instead: a numeric value below 1e12 is treated
// as seconds. 1e12 ms is 2001-09; every real epoch-seconds value is
// < 1e12 and every real epoch-ms value is >= 1e12, so existing `* 1000`
// callers (now >= 1e12) pass through unchanged — no double conversion.
// Numeric strings are parsed as numbers; other strings as dates.
export function toMs(ts) {
  let n;
  if (typeof ts === 'number') n = ts;
  else if (/^\d+(\.\d+)?$/.test(String(ts).trim())) n = Number(ts);
  else return Date.parse(ts);            // ISO / RFC date string → already ms
  if (Number.isNaN(n)) return NaN;
  return n < 1e12 ? n * 1000 : n;        // sub-1e12 → seconds, scale up
}

export function relTime(ts) {
  if (!ts) return '—';
  const t = toMs(ts);
  if (Number.isNaN(t)) return '—';
  const s = Math.floor((Date.now() - t) / 1000);
  if (s < 5) return 'now';
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

export function formatTs(ts) {
  if (!ts) return '';
  const t = toMs(ts);
  if (Number.isNaN(t)) return '';
  return new Date(t).toTimeString().slice(0, 8);
}

export function uptimeStr(startedAt) {
  if (!startedAt) return '—';
  const t = toMs(startedAt);
  if (Number.isNaN(t)) return '—';
  let s = Math.floor((Date.now() - t) / 1000);
  if (s < 60) return `${s}s`;
  const h = Math.floor(s / 3600);
  s -= h * 3600;
  const m = Math.floor(s / 60);
  s -= m * 60;
  if (h > 0) return `${h}h ${String(m).padStart(2, '0')}m`;
  return `${m}m ${String(s).padStart(2, '0')}s`;
}

// ── Status helpers ────────────────────────────────────────────────
// Process-level status (running/stopped/...) overlaid with semantic_status
// when present. semantic_status wins for visual treatment.
export function visualStatus(agent) {
  return agent.semantic_status || agent.status || 'idle';
}
